"""Offline tests for the read-only Play Protect certification model.

Run from the desktop directory:
    python3 -m unittest discover -s tests -p 'test_play_protect_certification.py'

No device, no network and no Google credential is involved: the CSR fixture is
a locally generated public registration request, and every other input is
synthetic.
"""
from pathlib import Path
import json
import sys
import types
import unittest


SCRIPTS = Path(__file__).resolve().parents[2] / "scripts"
sys.path.insert(0, str(SCRIPTS))
import play_protect_certification as model


