def options(**overrides):
    values = {
        "serial": "TEST-SERIAL",
        "offline": True,
        "attestation_chain": None,
        "roots_cache": None,
        "compat_active": None,
        "firewall_allows": None,
        "rkp_backend_status": None,
        "cache_file": "/nonexistent/catalog.json",
        "revocation_cache": "/nonexistent/status.json",
        "state_file": "/nonexistent/monitor.json",
        "component": "default",
        "out": None,
        "fail_on_blockers": False,
        "directory": None,
        "device": None,
    }
    values.update(overrides)
    return types.SimpleNamespace(**values)


class ShellResult:
    """Minimal stand-in for subprocess.CompletedProcess."""

    def __init__(self, stdout="", stderr="", returncode=0):
        self.stdout, self.stderr, self.returncode = stdout, stderr, returncode


FIRMWARE_REPLY = json.dumps({"reply": {"code": 200, "message": "", "value": {
    "new": None,
    "cur": {"latestVersion": "Step AOS 1.0.0.2.26001_stable_user_20261004_131555",
            "needUpdate": False, "existsUpdate": True,
            "releaseDate": "2026-10-16 17:37:46", "verType": "体验版"}}}})


class StubDevice:
    """Records every shell command so tests can assert read-only behaviour."""

    def __init__(self, props=None, replies=None, serial="TEST-SERIAL"):
        self.props = props or {}
        self.replies = replies or {}
        self.serial = serial
        self.commands = []

    def _run(self, args, timeout=40, check=True):
        self.commands.append(tuple(str(a) for a in args))
        return self.replies.get(tuple(str(a) for a in args), "")

    def raw(self, *args, timeout=40, check=True):
        return ShellResult(self.replies.get(tuple(str(a) for a in args), ""))

    def shell(self, *args, timeout=40):
        return self._run(list(args), timeout=timeout)

    def prop(self, name):
        return self.props.get(name, "")

    def connected(self):
        return True

    def verify_identity(self):
        return None

    # Delegate to the real implementation so the parsing logic under test is the
    # one that ships, not a re-implementation in the test.
    rpmb_props = model.Device.rpmb_props

    def identity(self):
        return {key: self.props.get("ro.product." + key, "") for key in
                ("brand", "manufacturer", "model", "device", "name")}


def catalog_html(rows):
    header = ("Retail Branding", "Marketing Name", "Device", "Model")
    body = [header] + [tuple(row) for row in rows]
    head = "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>" % row for row in body)
    return "<html><table>" + head + "</table></html>"


class ReadOnlyBoundaryTest(unittest.TestCase):
    def test_rkp_certify_is_not_reachable(self):
        self.assertNotIn("certify", model.RKP_READ_ONLY)
        self.assertEqual(sorted(model.RKP_READ_ONLY), ["csr", "dump", "list"])

    def test_script_source_never_implements_a_spoofing_path(self):
        source = (SCRIPTS / "play_protect_certification.py").read_text()
        for forbidden in ("ptrace", "finit_module", "Zygisk", "Magisk", "APatch",
                          "keybox.xml", "TrickyStore", "TEESimulator",
                          "PlayIntegrityFix", "PlayIntegrityFork"):
            self.assertNotIn(forbidden, source)


class RkpCsrParseTest(unittest.TestCase):
    def test_real_csr_yields_hal_identity_and_firmware(self):
        parsed = model.parse_rkp_csr(CSR)
        info = parsed["device_info"]
        self.assertEqual(info["manufacturer"], "QUALCOMM")
        self.assertEqual(info["brand"], "qti")
        self.assertEqual(info["model"], "Canoe for arm64")
        self.assertEqual(info["vb_state"], "green")
        self.assertEqual(info["security_level"], "tee")
        self.assertEqual(info["bootloader_state"], "locked")
        self.assertEqual(parsed["firmware_versions"],
                         ["ssg.tmefw.3.1-00483-release", "ssg.tmefw.4.0-01006-release"])
        self.assertEqual(len(parsed["sha256"]), 64)
        self.assertGreater(parsed["printable_share"], 0.5)

    def test_binary_valued_fields_are_not_invented(self):
        parsed = model.parse_rkp_csr(CSR)
        for field in ("vbmeta_digest", "boot_patch_level", "system_patch_level",
                      "vendor_patch_level"):
            self.assertIsNone(parsed["device_info"][field], field)
            self.assertIn(field, parsed["binary_fields"])

    def test_non_base64_is_rejected(self):
        for value in ("!!!not base64!!!", "", None, 12):
            with self.assertRaises(model.ProbeError):
                model.parse_rkp_csr(value)

    def test_dump_parser_separates_components(self):
        dump = model.parse_rkp_dump("default:\n  hwVersion=3\n  rpcAuthorName=Qualcomm\navf:\n  hwVersion=3\n")
        self.assertEqual(dump["default"]["rpcAuthorName"], "Qualcomm")
        self.assertEqual(dump["avf"]["hwVersion"], "3")
        self.assertNotIn("hwVersion", dump)


class LayerStateTest(unittest.TestCase):
    def test_unprobed_check_never_becomes_a_failure(self):
        checks = [model.check("a", 1, 1, None)]
        self.assertEqual(model.layer_state(checks), "unknown")
        self.assertIsNone(checks[0]["ok"])

    def test_all_checks_must_pass(self):
        self.assertEqual(model.layer_state([model.check("a", 1, 1, True)]), "pass")
        self.assertEqual(model.layer_state([model.check("a", 1, 1, True),
                                           model.check("b", 2, 2, False)]), "fail")

    def test_boolean_values_are_normalised(self):
        self.assertIs(model.check("a", 1, 1, 1)["ok"], True)
        self.assertIs(model.check("a", 0, 1, 0)["ok"], False)


class CatalogAliasTest(unittest.TestCase):
    def identity(self):
        return {"brand": "StepX", "manufacturer": "StepX", "model": "PZ261A",
                "device": "pandora", "name": "pandora"}

    def test_aliases_cover_every_reported_identity_field(self):
        self.assertEqual(model.catalog_aliases(self.identity()),
                         {"stepx", "pz261a", "pandora"})

    def test_blank_and_duplicate_fields_are_dropped(self):
        aliases = model.catalog_aliases({"brand": " StepX ", "manufacturer": "stepx",
                                        "model": "", "device": None, "name": "pandora"})
        self.assertEqual(aliases, {"stepx", "pandora"})

    def test_shared_codename_is_reported_but_never_counts_as_listed(self):
        rows = model.parse_supported_devices(
            catalog_html([["Xiaomi", "Xiaomi 17 Pro", "pandora", "25098PN5AC"]]))
        identity = self.identity()
        found = [row for row in rows
                 if any(cell.strip().casefold() in model.catalog_aliases(identity)
                        for cell in row)]
        self.assertEqual(len(found), 1)
        match, _ = model.match_catalog(rows, identity)
        self.assertIsNone(match)

    def test_unrelated_catalog_is_a_definitive_negative(self):
        rows = model.parse_supported_devices(
            catalog_html([["Other", "Other Phone", "lake", "OT100"]]))
        hits = [row for row in rows
                if any(cell.strip().casefold() in model.catalog_aliases(self.identity())
                       for cell in row)]
        self.assertEqual(hits, [])


class RkpConfigurationTest(unittest.TestCase):
    def stub(self):
        return StubDevice(
            props={"ro.serialno": "TEST-SERIAL",
                   "remote_provisioning.enable_rkpd": "false",
                   "remote_provisioning.hostname": "",
                   "ro.oem.keybox.attestation": "",
                   "persist.deviceconfig.remotekeyprovisioningnative.enablerkpd": ""},
            replies={
                ("pm", "list", "packages", "--user", "0"):
                    "package:com.android.rkpdapp\npackage:com.android.vending",
                ("ps", "-A", "-o", "NAME"): "root\nsystem\ncom.android.rkpdapp\n",
                ("cmd", "remote_provisioning", "dump"):
                    "default:\n  hwVersion=3\n  rpcAuthorName=Qualcomm\n"
                    "  uniqueId=fae4f65f6f801f67bbc9598ea5768b9d\n"
                    "  supportedNumKeysInCsr=20\navf:\n  hwVersion=3\n",
                ("cmd", "remote_provisioning", "list"): "default\navf\n",
                ("cmd", "remote_provisioning", "csr", "default"): CSR,
                ("getprop",): "[remote_provisioning.hostname]: []\n"
                              "[remote_provisioning.enable_rkpd]: [false]\n"
                              "[vendor.stepos.rpmb.provisioned]: [true]\n"
                              "[persist.sys.stepos.region]: [CN]\n",
                ("pm", "path", "com.android.rkpdapp"):
                    "package:/apex/com.android.rkpd/priv-app/rkpdapp@B/rkpdapp.apk",
            })

    def test_rpmb_markers_are_parsed_from_the_vendor_namespace(self):
        self.assertEqual(self.stub().rpmb_props(),
                         {"vendor.stepos.rpmb.provisioned": "true"})

    def test_rpmb_parsing_survives_values_containing_colons(self):
        device = self.stub()
        device.replies[("getprop",)] = "[vendor.stepos.rpmb.provisioned]: [true:yes]\n"
        self.assertEqual(device.rpmb_props(),
                         {"vendor.stepos.rpmb.provisioned": "true:yes"})

    def test_csr_probe_is_paired_with_the_hal_dump(self):
        parsed = model.probe_csr(self.stub(), "default")
        self.assertEqual(parsed["unique_id"], "fae4f65f6f801f67bbc9598ea5768b9d")
        self.assertEqual(parsed["rpc_author"], "Qualcomm")
        self.assertEqual(parsed["hw_version"], "3")
        self.assertEqual(parsed["device_info"]["security_level"], "tee")

    def test_rkp_configuration_block_records_every_knob(self):
        state = {"offline": True, "firewall_allows_rkp": False, "rkp_backend_status": 444,
                 "catalog": {"listed": False, "note": "未收录"}, "compat_active": None}
        layer = model.probe_rkp(self.stub(), state)
        config = layer["rkp_configuration"]
        self.assertEqual(config["remote_provisioning.hostname"], "")
        self.assertEqual(config["remote_provisioning.enable_rkpd"], "false")
        self.assertEqual(config["rpmb_provisioned"], "true")
        self.assertTrue(config["rkpdapp_apk"].startswith("package:/apex/com.android.rkpd"))
        # enable_rkpd=false is the AOSP default and must not be flagged as a fault.
        self.assertIn("不是故障", config["note"])
        running = [c for c in layer["checks"] if c["check"] == "com.android.rkpdapp 正在运行"]
        self.assertEqual(running[0]["ok"], True)
        self.assertEqual(layer["state"], "fail")


class MultiComponentCsrTest(unittest.TestCase):
    def stub(self):
        return StubDevice(
            props={"ro.serialno": "TEST-SERIAL"},
            replies={
                ("pm", "list", "packages", "--user", "0"):
                    "package:com.android.rkpdapp\npackage:com.android.vending",
                ("ps", "-A", "-o", "NAME"): "com.android.rkpdapp\n",
                ("cmd", "remote_provisioning", "list"): "default\navf\n",
                ("cmd", "remote_provisioning", "csr", "default"): CSR,
                ("cmd", "remote_provisioning", "csr", "avf"): CSR,
                ("cmd", "remote_provisioning", "dump"):
                    "default:\n  hwVersion=3\n  rpcAuthorName=Qualcomm\n"
                    "  uniqueId=fae4f65f6f801f67bbc9598ea5768b9d\n"
                    "avf:\n  hwVersion=3\n  rpcAuthorName=Android Virtualization Framework\n"
                    "  uniqueId=AVF Remote Provisioning 1\n",
                ("getprop",): "[remote_provisioning.hostname]: []\n",
                ("pm", "path", "com.android.rkpdapp"): "package:/apex/x.apk",
            })

    def test_every_component_gets_its_own_csr(self):
        parsed = model.probe_rkp_csr_all(self.stub(), ["default", "avf"])
        self.assertEqual([entry["component"] for entry in parsed], ["default", "avf"])
        for entry in parsed:
            self.assertEqual(entry["device_info"]["manufacturer"], "QUALCOMM")

    def test_unknown_component_is_reported_not_raised(self):
        parsed = model.probe_rkp_csr_all(self.stub(), ["default", "missing"])
        self.assertEqual(parsed[1]["component"], "missing")
        self.assertIn("error", parsed[1])

    def test_two_identities_are_called_out_in_the_layer_note(self):
        state = {"offline": False, "firewall_allows_rkp": False, "rkp_backend_status": 444,
                 "catalog": {"listed": False, "note": "未收录"}, "compat_active": None,
                 "revocation_cache": "/nonexistent/status.json"}
        layer = model.probe_rkp(self.stub(), state)
        self.assertIn("2 个 RKP 登记身份", layer["note"])
        self.assertIn("default=qti", layer["note"])
        # The stub replays one CSR for both components, so both report `qti`;
        # on a real device avf reports `aosp-avf` (see the ticket's 4.2.1).
        self.assertIn("avf=qti", layer["note"])

    def test_offline_mode_skips_csr_generation(self):
        state = {"offline": True, "firewall_allows_rkp": False, "rkp_backend_status": 444,
                 "catalog": {"listed": False, "note": "未收录"}, "compat_active": None,
                 "revocation_cache": "/nonexistent/status.json"}
        layer = model.probe_rkp(self.stub(), state)
        self.assertNotIn("rkp_csr_components", layer)


class EnglishEscalationTest(unittest.TestCase):
    """The English ticket must stay fully English as the model evolves."""

    def test_every_layer_has_an_english_title(self):
        for layer in model.LAYERS:
            self.assertTrue(layer.get("title_en"), layer["id"])
            self.assertRegex(layer["title_en"], r"^Layer \d - ")

    def test_every_action_has_an_english_label_and_reason(self):
        for item in model.LEVERAGE:
            self.assertTrue(item.get("action_en"), item["action"])
            self.assertTrue(item.get("reason_en"), item["action"])

    def test_english_ticket_contains_no_cjk(self):
        import contextlib
        import io
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            code = model.command_ticket_en(options(offline=True, device=StubDevice()))
        self.assertEqual(code, 0)
        text = buffer.getvalue()
        cjk = [ch for ch in text if '\u4e00' <= ch <= '\u9fff']
        self.assertEqual(cjk, [], f"English ticket still contains CJK: {''.join(sorted(set(cjk)))}")
        for marker in ("NOT CERTIFIED", "Layer 3 - hardware key attestation",
                       "RKP hardware public key", "AttestationRootHostTest",
                       "Device not registered"):
            self.assertIn(marker, text)

    def test_english_ticket_written_to_a_file(self):
        import contextlib
        import io
        import tempfile
        with tempfile.TemporaryDirectory() as scratch:
            target = Path(scratch) / "ticket-en.md"
            buffer = io.StringIO()
            with contextlib.redirect_stdout(buffer):
                code = model.command_ticket_en(
                    options(offline=True, device=StubDevice(), out=str(target)))
            self.assertEqual(code, 0)
            self.assertEqual(json.loads(buffer.getvalue())["verdict"], "not_certified")
            self.assertIn("Required actions", target.read_text())

    def test_chinese_ticket_is_unchanged_by_the_english_variant(self):
        import contextlib
        import io
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            model.command_ticket(options(offline=True, device=StubDevice()))
        self.assertIn("需要厂商完成的动作（按杠杆排序）", buffer.getvalue())


class SecurityPatchTest(unittest.TestCase):
    """Patch freshness is a Play Integrity factor, never a certification input."""

    def device(self, patch="2025-12-05", vendor="2025-12-05"):
        return StubDevice(props={"ro.build.version.security_patch": patch,
                                 "ro.vendor.build.security_patch": vendor})

    def test_age_is_measured_from_the_newest_patch_level(self):
        result = model.probe_security_patch(self.device())
        self.assertEqual(result["security_patch"], "2025-12-05")
        self.assertEqual(result["vendor_security_patch"], "2025-12-05")
        self.assertIsInstance(result["age_days"], int)
        self.assertGreater(result["age_days"], 300)
        self.assertTrue(result["stale"])
        self.assertIn("MEETS_DEVICE_INTEGRITY", result["note"])

    def test_yyyymmdd_format_is_also_accepted(self):
        result = model.probe_security_patch(self.device(patch="20251205", vendor=""))
        self.assertEqual(result["security_patch"], "20251205")
        self.assertIsNone(result["vendor_security_patch"])
        self.assertGreater(result["age_days"], 300)

    def test_unparsable_patch_level_is_unknown_not_a_verdict(self):
        result = model.probe_security_patch(self.device(patch="unknown", vendor=""))
        self.assertIsNone(result["age_days"])
        self.assertIsNone(result["stale"])
        self.assertIn("未能解析", result["note"])

    def test_missing_property_is_unknown_not_a_verdict(self):
        result = model.probe_security_patch(StubDevice(props={}))
        self.assertIsNone(result["security_patch"])
        self.assertIsNone(result["stale"])

    def test_a_fresh_patch_is_not_flagged(self):
        import datetime
        today = datetime.datetime.now(datetime.timezone.utc).date()
        result = model.probe_security_patch(self.device(patch=today.isoformat()))
        self.assertFalse(result["stale"])
        self.assertLessEqual(result["age_days"], 1)

    def test_patch_age_never_changes_the_certification_verdict(self):
        report = model.report(self.device(), options(offline=True))
        self.assertEqual(report["verdict"], "not_certified")
        self.assertIsInstance(report["patch_freshness"], dict)
        # The verdict is derived from the four layers only.
        self.assertNotIn("age_days", json.dumps(
            {layer["layer"]: layer["state"] for layer in report["layers"]}))
        self.assertTrue(any("patch_freshness 不参与认证判定" in item
                            for item in report["limitations"]))

    def test_ticket_reports_the_age_without_claiming_a_threshold(self):
        import contextlib
        import io
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            model.command_ticket(options(offline=True, device=self.device()))
        text = buffer.getvalue()
        self.assertIn("安全补丁新鲜度（风险因素，不影响上面的认证判定）", text)
        self.assertIn("距今天数：", text)
        self.assertIn("Google 未公布阈值", text)


class UpdateQueryServiceTest(unittest.TestCase):
    """The vendor's own update service is the last read-only route; record why it closes."""

    DUMP = (
        "Activity Resolver Table:\n"
        "  com.stepos.update.QUERY_UPDATE:\n"
        "    43dba02 com.stepos.update/.download.QueryUpdateService filter c80ff13 "
        "permission com.stepos.update.QUERY_UPDATE\n"
        "Permissions:\n"
        "  Permission [com.stepos.update.QUERY_UPDATE] (4f9d72e):\n"
        "    sourcePackage=com.stepos.update\n"
        "    uid=1000 gids=[] type=0 prot=signature\n"
        "    perm=PermissionInfo{6c12762 com.stepos.update.QUERY_UPDATE}\n"
        "    flags=0x0\n"
    )

    def device(self, dump=None, shell_holds=False):
        replies = {("dumpsys", "package", "com.stepos.update"): dump if dump is not None else self.DUMP}
        replies[("dumpsys", "package", "com.android.shell")] = (
            "com.stepos.update.QUERY_UPDATE: granted=true\n" if shell_holds
            else "android.permission.INTERNET: granted=true\n")
        return StubDevice(props={"ro.serialno": "TEST-SERIAL"}, replies=replies)

    def test_signature_permission_is_measured_not_assumed(self):
        result = model.probe_update_query_service(self.device())
        self.assertTrue(result["service_present"])
        self.assertEqual(result["guard_permission"],
                         "com.stepos.update.QUERY_UPDATE")
        self.assertEqual(result["protection_level"], "signature")
        self.assertFalse(result["host_holds_permission"])
        self.assertIn("只返回更新器已缓存的结果", result["note"])

    def test_a_host_held_permission_is_reported_as_such(self):
        result = model.probe_update_query_service(self.device(shell_holds=True))
        self.assertTrue(result["host_holds_permission"])
        self.assertIn("宿主 shell 持有", result["note"])

    def test_privileged_and_normal_levels_are_both_parsed(self):
        for level in ("signature|privileged", "normal", "signature|knownSigner"):
            dump = self.DUMP.replace("prot=signature", f"prot={level}")
            result = model.probe_update_query_service(self.device(dump=dump))
            self.assertEqual(result["protection_level"], level, level)

    def test_missing_service_is_reported_not_raised(self):
        result = model.probe_update_query_service(self.device(dump="nothing here"))
        self.assertFalse(result["service_present"])
        self.assertIn("未找到", result["note"])

    def test_unreachable_device_degrades(self):
        class Dead(StubDevice):
            def shell(self, *args, timeout=40):
                raise model.ProbeError("手机连接未授权或已离线，请重新连接")

        result = model.probe_update_query_service(Dead())
        self.assertIsNone(result["service_present"])
        self.assertIn("未读取到", result["note"])

    def test_the_closure_never_changes_the_verdict(self):
        report = model.report(self.device(), options(offline=True))
        self.assertEqual(report["verdict"], "not_certified")
        self.assertIsInstance(report["update_query_service"], dict)


class CompatPatchAuthorityTest(unittest.TestCase):
    """Layer 1 must trust the compatibility component, not a foreground guess."""

    VALID = json.dumps({
        "ok": True, "supported": True, "active": True, "can_rollback": True,
        "official_certification_changed": False,
        "scopes": {"gms": {"cache_active": True, "db_active": True},
                   "play": {"cache_active": True, "db_active": True}},
        "message": "兼容补丁已生效；这不改变 Google 的设备认证。",
        "receipt_id": "compat-20261023T045504-3e5e6ba69030800f",
    })

    def script(self, body, executable=True):
        import tempfile
        scratch = tempfile.mkdtemp(prefix="stepx-compat-")
        path = Path(scratch) / "compat.py"
        path.write_text("#!/usr/bin/env python3\nimport sys\n"
                        f"sys.stdout.write({body!r})\n")
        if executable:
            path.chmod(0o700)
        return path

    def device(self):
        return StubDevice(props={"ro.serialno": "TEST-SERIAL"}, replies={
            ("dumpsys", "activity", "activities"): "mTopResumedActivity=U",
            ("pm", "list", "packages", "--user", "0"):
                "package:com.google.android.gsf\npackage:com.google.android.gms\n"
                "package:com.android.vending",
            ("pm", "list", "packages", "-d", "--user", "0"): "",
        })

    def state(self, **extra):
        base = {"compat_patch": None, "adb_path": None, "offline": True}
        base.update(extra)
        return base

    def test_the_component_verdict_is_used_verbatim(self):
        result = model.probe_compat_patch(self.device(), script=str(self.script(self.VALID)))
        self.assertTrue(result["available"])
        self.assertTrue(result["active"])
        self.assertTrue(result["can_rollback"])
        self.assertFalse(result["official_certification_changed"])
        self.assertEqual(result["scopes"]["gms"], {"cache_active": True, "db_active": True})

    def test_the_private_receipt_id_is_never_surfaced(self):
        result = model.probe_compat_patch(self.device(), script=str(self.script(self.VALID)))
        self.assertNotIn("receipt_id", result)
        self.assertNotIn("compat-2026", json.dumps(result))

    def test_invalid_json_is_reported_not_guessed(self):
        result = model.probe_compat_patch(self.device(), script=str(self.script("not json")))
        self.assertFalse(result["available"])
        self.assertIn("未返回有效状态", result["reason"])

    def test_incomplete_payload_is_rejected(self):
        for key in ("ok", "supported", "active", "can_rollback",
                    "official_certification_changed", "scopes"):
            payload = json.loads(self.VALID)
            payload.pop(key)
            result = model.probe_compat_patch(
                self.device(), script=str(self.script(json.dumps(payload))))
            self.assertFalse(result["available"], key)
            self.assertIn(key, result["reason"])

    def test_a_patch_that_touched_certification_is_flagged(self):
        payload = json.loads(self.VALID)
        payload["official_certification_changed"] = True
        state = self.state(compat_patch=model.probe_compat_patch(
            self.device(), script=str(self.script(json.dumps(payload)))))
        layer = model.probe_client_admission(self.device(), state)
        boundary = next(c for c in layer["checks"] if c["check"] == "兼容补丁未改动设备认证")
        self.assertIs(boundary["ok"], False)
        # A patch that crossed the line must not be reported as store usability.
        self.assertFalse(layer["store_usable"])

    def test_an_inactive_patch_is_not_reported_as_usable(self):
        payload = json.loads(self.VALID)
        payload["active"] = False
        state = self.state(compat_patch=model.probe_compat_patch(
            self.device(), script=str(self.script(json.dumps(payload)))))
        layer = model.probe_client_admission(self.device(), state)
        self.assertFalse(layer["store_usable"])
        self.assertEqual(layer["state"], "fail")

    def test_missing_component_degrades_to_unknown_not_a_failure(self):
        state = self.state(compat_patch={"available": False, "reason": "未找到 Play 兼容补丁组件"})
        layer = model.probe_client_admission(self.device(), state)
        entry = next(c for c in layer["checks"] if c["check"] == "Play 兼容补丁生效")
        self.assertIsNone(entry["ok"])
        self.assertEqual(layer["state"], "unknown")

    def test_layer_one_now_reports_five_checks(self):
        state = self.state(compat_patch=model.probe_compat_patch(
            self.device(), script=str(self.script(self.VALID))))
        layer = model.probe_client_admission(self.device(), state)
        self.assertEqual([c["check"] for c in layer["checks"]],
                         ["Google 三件套已安装", "组件被停用", "当前前台为未认证拦截页",
                          "Play 兼容补丁生效", "兼容补丁未改动设备认证"])
        self.assertTrue(layer["store_usable"])


class FirmwareChannelTest(unittest.TestCase):
    """The official firmware channel is reachable; the newer OTA probe is not."""

    REPLY = json.dumps({"reply": {"code": 200, "message": "", "value": {
        "new": None,
        "cur": {"latestVersion": "Step AOS 1.0.0.2.26001_stable_user_20261004_131555",
                "systemVersion": "1.0.0.2", "releaseDate": "2026-10-16 17:37:46",
                "verType": "体验版", "fileSize": "6.26 GB",
                "digest": "80ef5d1725d14dc73c5ddc24c4add57d",
                "updateUrl": "https://ota-firmware.stepaos.com/x/update.zip",
                "needUpdate": False, "existsUpdate": True}}}})

    NEWER = json.dumps({"reply": {"code": 200, "message": "", "value": {
        "new": {"latestVersion": "Step AOS 1.0.0.3.99999_stable_user_20261101_000000"},
        "cur": {"latestVersion": "Step AOS 1.0.0.2.26001_stable_user_20261004_131555",
                "needUpdate": True, "existsUpdate": True}}}})

    def device(self, body=REPLY):
        class Firmware(StubDevice):
            def raw(self, *args, timeout=40, check=True):
                joined = " ".join(str(a) for a in args)
                if "OtaMetadataProbe" in joined:
                    return ShellResult(body, "Firmware metadata HTTP 200")
                if str(args[0]) == "push":
                    return ShellResult("1 file pushed")
                return ShellResult("")

        return Firmware(props={
            "ro.serialno": "TEST-SERIAL",
            "ro.build.aios_version": "Step AOS 1.0.0.2.26001_stable_user_20261004_131555",
            "ro.build.mask.id": "",
            "ro.build.version.incremental": "172",
            "ro.build.fingerprint": "StepX/pandora/pandora:16/B/172:user/release-keys",
            "ro.build.version.security_patch": "2025-12-05",
        })

    def test_no_newer_build_is_reported_as_such(self):
        result = model.probe_firmware(self.device())
        self.assertTrue(result["available"])
        self.assertEqual(result["http_code"], 200)
        self.assertIsNone(result["new_version"])
        self.assertEqual(result["latest_version"],
                         "Step AOS 1.0.0.2.26001_stable_user_20261004_131555")
        self.assertFalse(result["need_update"])
        self.assertEqual(result["digest"], "80ef5d1725d14dc73c5ddc24c4add57d")

    def test_a_newer_build_is_distinguished_from_no_update(self):
        result = model.probe_firmware(self.device(self.NEWER))
        self.assertEqual(result["new_version"],
                         "Step AOS 1.0.0.3.99999_stable_user_20261101_000000")
        self.assertTrue(result["need_update"])

    def test_command_reports_whether_the_device_is_already_latest(self):
        import contextlib
        import io
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            code = model.command_firmware(options(device=self.device()))
        self.assertEqual(code, 0)
        payload = json.loads(buffer.getvalue())
        self.assertTrue(payload["same_as_current"])
        self.assertIsNone(payload["new_version"])
        self.assertEqual(payload["current_incremental"], "172")
        self.assertEqual(payload["security_patch"], "2025-12-05")

    def test_command_flags_a_device_that_is_behind(self):
        import contextlib
        import io
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            model.command_firmware(options(device=self.device(self.NEWER)))
        payload = json.loads(buffer.getvalue())
        self.assertFalse(payload["same_as_current"])
        self.assertIsNotNone(payload["new_version"])

    def test_unparsable_reply_is_not_a_verdict(self):
        result = model.probe_firmware(self.device("not json at all"))
        self.assertFalse(result["available"])
        self.assertIn("未返回有效固件信息", result["note"])

    def test_missing_probe_artifacts_are_reported(self):
        result = model.probe_firmware(self.device())
        self.assertTrue(result["available"])  # prebuilt dex is used when present

    def test_firmware_state_never_feeds_the_certification_verdict(self):
        # A read-only firmware answer is not a certification input: it may be
        # absent, and it never moves the verdict either way.
        report = model.report(self.device(), options(offline=True))
        self.assertEqual(report["verdict"], "not_certified")
        self.assertIsNone(report["firmware"])


class MonitorTest(unittest.TestCase):
    """A change report must reflect the device, not the caller's flag choices."""

    def device(self):
        return StubDevice(props={
            "ro.serialno": "TEST-SERIAL",
            "ro.product.brand": "StepX", "ro.product.manufacturer": "StepX",
            "ro.product.model": "PZ261A", "ro.product.device": "pandora",
            "ro.product.name": "pandora", "ro.build.tags": "release-keys",
            "ro.build.type": "user", "ro.boot.flash.locked": "1",
            "ro.build.verifiedbootstate": "green", "ro.build.version.sdk": "36",
            "ro.build.fingerprint": "StepX/pandora/pandora:16/B/172:user/release-keys",
            "ro.build.version.security_patch": "2025-12-05",
            "remote_provisioning.hostname": "",
        }, replies={
            ("get-state",): "device",
            ("dumpsys", "activity", "activities"): "mTopResumedActivity=U",
            ("pm", "list", "packages", "--user", "0"):
                "package:com.google.android.gsf\npackage:com.google.android.gms\n"
                "package:com.android.vending\npackage:com.android.rkpdapp",
            ("pm", "list", "packages", "-d", "--user", "0"): "",
            ("ps", "-A", "-o", "NAME"): "com.android.rkpdapp\n",
            ("getenforce",): "Enforcing",
            ("cmd", "remote_provisioning", "dump"):
                "default:\n  hwVersion=3\n  rpcAuthorName=Qualcomm\n  uniqueId=abc\n",
            ("cmd", "remote_provisioning", "list"): "default\n",
            ("getprop",): "[vendor.stepos.rpmb.provisioned]: [true]\n",
            ("pm", "path", "com.android.rkpdapp"): "package:/apex/x.apk",
        })

    def run_monitor(self, state_file, **overrides):
        import contextlib
        import io
        values = {"offline": True, "device": self.device(), "state_file": str(state_file),
                  "firewall_allows": None, "rkp_backend_status": None,
                  "attestation_chain": None, "compat_active": None}
        values.update(overrides)
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            code = model.command_monitor(options(**values))
        return code, json.loads(buffer.getvalue())

    def test_baseline_then_identical_run_reports_no_change(self):
        import tempfile
        with tempfile.TemporaryDirectory() as scratch:
            state = Path(scratch) / "monitor.json"
            code, first = self.run_monitor(state)
            self.assertEqual(code, 0)
            self.assertTrue(first["baseline_established"])
            self.assertFalse(first["changed"])
            _, second = self.run_monitor(state)
            self.assertTrue(second["same_flags"])
            self.assertFalse(second["changed"])
            self.assertIn("未变化", second["message"])

    def test_changing_only_the_flags_is_not_reported_as_a_state_change(self):
        import tempfile
        with tempfile.TemporaryDirectory() as scratch:
            state = Path(scratch) / "monitor.json"
            self.run_monitor(state)
            code, second = self.run_monitor(state, firewall_allows=False,
                                            rkp_backend_status=444)
            self.assertEqual(code, 0)
            self.assertFalse(second["changed"])
            self.assertFalse(second["same_flags"])
            self.assertIn("取证参数与基线不同", second["message"])
            self.assertTrue(any("不一致" in item for item in second["diff"]))

    def test_a_stable_flag_set_gives_a_clean_second_comparison(self):
        import tempfile
        with tempfile.TemporaryDirectory() as scratch:
            state = Path(scratch) / "monitor.json"
            self.run_monitor(state, firewall_allows=False, rkp_backend_status=444)
            self.run_monitor(state, firewall_allows=False, rkp_backend_status=444)
            _, third = self.run_monitor(state, firewall_allows=False,
                                        rkp_backend_status=444)
            self.assertTrue(third["same_flags"])
            self.assertFalse(third["changed"])

    def test_a_real_evidence_change_is_reported_with_a_precise_diff(self):
        import tempfile
        with tempfile.TemporaryDirectory() as scratch:
            state = Path(scratch) / "monitor.json"
            self.run_monitor(state)
            saved = json.loads(state.read_text())
            saved["fingerprint"]["verdict"] = "certified"
            saved["fingerprint"]["blocker_layers"] = []
            state.write_text(json.dumps(saved))
            code, changed = self.run_monitor(state)
            self.assertEqual(code, 0)
            self.assertTrue(changed["changed"])
            self.assertTrue(changed["same_flags"])
            self.assertTrue(any("认证判定" in item for item in changed["diff"]))

    def test_the_fingerprint_never_contains_unprobed_markers(self):
        import tempfile
        with tempfile.TemporaryDirectory() as scratch:
            state = Path(scratch) / "monitor.json"
            self.run_monitor(state, firewall_allows=False, rkp_backend_status=444)
            _, payload = self.run_monitor(state, firewall_allows=False,
                                          rkp_backend_status=444)
            self.assertNotIn("未探测", json.dumps(payload["current"], ensure_ascii=False))

    def test_fail_on_blockers_returns_nonzero_while_uncertified(self):
        import tempfile
        with tempfile.TemporaryDirectory() as scratch:
            state = Path(scratch) / "monitor.json"
            code, _ = self.run_monitor(state, fail_on_blockers=True)
            self.assertEqual(code, 1)


class ExplainTest(unittest.TestCase):
    """`explain` is the mechanism-cognition artifact; it must stay in sync."""

    def text(self):
        import contextlib
        import io
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            code = model.command_explain(options(offline=True))
        self.assertEqual(code, 0)
        return buffer.getvalue()

    def test_every_layer_is_described_with_its_owner(self):
        text = self.text()
        for layer in model.LAYERS:
            self.assertIn(layer["title"], text)
            self.assertIn(layer["question"], text)
            for item in layer["google_checks"]:
                self.assertIn(item, text)

    def test_leverage_order_matches_the_constant(self):
        text = self.text()
        section = text[text.index("按杠杆排序的厂商侧动作"):]
        positions = [section.index(item["action"]) for item in model.LEVERAGE]
        self.assertEqual(positions, sorted(positions), "工单与 explain 的杠杆顺序不一致")
        # RKP registration must lead, not the factory keybox.
        self.assertLess(section.index("向 Google RKP 后台登记硬件公钥"),
                        section.index("产线烧录 Google 签发的生产 Keybox"))

    def test_the_rkp_inference_is_labelled_as_an_inference(self):
        self.assertIn("**这是推断**", self.text())

    def test_current_findings_are_all_present(self):
        text = self.text()
        for marker in ("双 RKP 登记身份" if "双 RKP 登记身份" in text else "两个 RKP 登记身份",
                       "1765", "Key Attestation CA1", "安全补丁", "没有比设备当前版本更新的构建",
                       "com.stepos.feedback", "GSF Android ID", "official_certification_changed"):
            self.assertIn(marker, text, marker)

    def test_no_spoofing_path_is_ever_suggested(self):
        text = self.text()
        self.assertIn("本工具不实现", text)
        for forbidden in ("keybox.xml", "TrickyStore", "PlayIntegrityFix", "伪装机型指纹即可"):
            self.assertNotIn(forbidden, text)

    def test_the_two_verdicts_are_kept_separate(self):
        text = self.text()
        self.assertIn("商店可用性（第 1 层）", text)
        self.assertIn("设备认证（四层联合）", text)
        self.assertIn("不构成认证", text)


class ModelValidationTest(unittest.TestCase):
    """The model must be able to say `certified`; otherwise it proves nothing."""

    def build(self, **overrides):
        states = {layer["id"]: "pass" for layer in model.LAYERS}
        states.update(overrides)
        results = []
        for layer in model.LAYERS:
            result = {"layer": layer["id"], "title": layer["title"],
                      "owner": layer["owner"], "state": states[layer["id"]],
                      "checks": [], "note": ""}
            if layer["id"] == "rkp_and_catalog":
                result["checks"] = [
                    model.check("RKP signCertificates", overrides.get("backend", 200), "200",
                                overrides.get("backend", 200) == 200),
                    model.check("Google 认证设备目录收录", overrides.get("listed", True), True,
                                overrides.get("listed", True) is True),
                ]
            if layer["id"] == "key_attestation":
                result["verification"] = {
                    "official_root_match": overrides.get("root_match", True)}
            results.append(result)
        return results

    def test_a_fully_green_device_is_certified(self):
        self.assertTrue(model.certify(self.build()))

    def test_each_layer_alone_blocks_certification(self):
        for layer in model.LAYER_IDS:
            with self.subTest(layer=layer):
                self.assertFalse(model.certify(self.build(**{layer: "fail"})), layer)

    def test_a_client_side_patch_alone_never_certifies(self):
        layers = self.build(backend=444, listed=False, root_match=False)
        self.assertEqual(layers[0]["state"], "pass")
        self.assertFalse(model.certify(layers))

    def test_an_unprobed_layer_blocks_certification(self):
        self.assertFalse(model.certify(self.build(key_attestation="unknown")))

    def test_the_documented_positive_control_is_named(self):
        doc = (Path(__file__).resolve().parents[2] / "docs"
               / "play-protect-certification-model.md").read_text(encoding="utf-8")
        self.assertIn("ASGXVB1806001948", doc)
        self.assertIn("never addressed", doc)
        self.assertIn("不主动探测第二台设备", doc)


class RkpPoolTest(unittest.TestCase):
    """`certify` can read the local pool, but only when it cannot reach Google."""

    def device(self, hostname="", reply=""):
        class Pool(StubDevice):
            def raw(self, *args, timeout=40, check=True):
                if "certify" in " ".join(str(a) for a in args):
                    return ShellResult(reply)
                return ShellResult("")

        return Pool(props={"ro.serialno": "TEST-SERIAL",
                           "remote_provisioning.hostname": hostname})

    def test_it_refuses_to_run_when_a_hostname_is_set(self):
        result = model.probe_rkp_pool(self.device(hostname="remoteprovisioning.googleapis.com"))
        self.assertEqual(result["pool_state"], "unknown")
        self.assertIn("已拒绝执行", result["note"])

    def test_a_firewall_block_is_reported_as_unreachable_not_empty(self):
        result = model.probe_rkp_pool(self.device(reply=(
            "java.util.concurrent.CompletionException: android.os.RemoteException: "
            "Failed to bind to IRemoteProvisioning service")))
        self.assertEqual(result["pool_state"], "unreachable")
        self.assertIn("连本地证书池都读不到", result["note"])

    def test_a_provisioned_chain_is_reported_as_such(self):
        result = model.probe_rkp_pool(self.device(reply=(
            "-----BEGIN CERTIFICATE-----\\nMIIB\\n-----END CERTIFICATE-----")))
        self.assertEqual(result["pool_state"], "provisioned")

    def test_a_444_reply_means_the_pool_is_empty(self):
        result = model.probe_rkp_pool(self.device(reply=(
            "RkpProxyException: ERROR_PERMANENT: HTTP error status encountered: 444")))
        self.assertEqual(result["pool_state"], "empty")
        self.assertIn("从未被成功签发", result["note"])

    def test_an_unexplained_reply_stays_unknown(self):
        result = model.probe_rkp_pool(self.device(reply="something else entirely"))
        self.assertEqual(result["pool_state"], "unknown")
        self.assertIn("无法解释", result["note"])

    def test_a_transport_failure_degrades(self):
        class Dead(StubDevice):
            def prop(self, name):
                return ""

            def raw(self, *args, timeout=40, check=True):
                raise model.ProbeError("手机连接未授权或已离线，请重新连接")

        result = model.probe_rkp_pool(Dead())
        self.assertEqual(result["pool_state"], "unknown")
        self.assertIn("无法执行", result["note"])


class DeliverableConsistencyTest(unittest.TestCase):
    """`explain`, the doc and both tickets must never contradict each other.

    A previous round found `explain` still leading with the factory keybox while
    the doc and ticket had established RKP registration as the highest-leverage
    action. These tests keep that class of drift from coming back.
    """

    DOC = (Path(__file__).resolve().parents[2] / "docs"
           / "play-protect-certification-model.md")

    def explain(self):
        import contextlib
        import io
        buffer = io.StringIO()
        with contextlib.redirect_stdout(buffer):
            code = model.command_explain(options(offline=True))
        self.assertEqual(code, 0)
        return buffer.getvalue()

    def ticket(self, english=False):
        import contextlib
        import io
        buffer = io.StringIO()
        handler = model.command_ticket_en if english else model.command_ticket
        with contextlib.redirect_stdout(buffer):
            code = handler(options(offline=True, device=StubDevice()))
        self.assertEqual(code, 0)
        return buffer.getvalue()

    # Each OEM action has one marker word that is unique to it, so the order can
    # be compared across deliverables that phrase the action differently.
    MARKERS = ("登记", "防火墙", "CTS", "Keybox")

    @staticmethod
    def numbered_list(section):
        """Slice to the enumerated actions, skipping any prose above them."""
        import re
        match = re.search(r"^\s*1[.、]\s", section, re.M)
        return section[match.start():] if match else section

    def test_leverage_order_is_identical_across_deliverables(self):
        doc = self.DOC.read_text(encoding="utf-8")
        table = doc[doc.index("| 优先级 | 动作 | 责任方 | 可解除的层 |"):]
        table = table[:table.index("\n\n")]
        positions = [table.index(marker) for marker in self.MARKERS]
        self.assertEqual(positions, sorted(positions),
                         "文档表格的杠杆顺序与 LEVERAGE 不一致")
        for text, label in ((self.explain(), "explain"), (self.ticket(), "工单")):
            section = self.numbered_list(text[text.index("按杠杆排序"):])
            spots = [section.index(marker) for marker in self.MARKERS]
            self.assertEqual(spots, sorted(spots), f"{label} 的杠杆顺序与 LEVERAGE 不一致")

    def test_rkp_registration_leads_everywhere(self):
        for text, label in ((self.explain(), "explain"), (self.ticket(), "工单")):
            section = self.numbered_list(text[text.index("按杠杆排序"):])
            self.assertLess(section.index("登记"), section.index("Keybox"), label)
            self.assertLess(section.index("登记"), section.index("防火墙"), label)

    def test_both_official_roots_are_named_in_explain_and_doc(self):
        doc = self.explain() + self.DOC.read_text(encoding="utf-8")
        for root in ("f92009e853b6b045", "Key Attestation CA1"):
            self.assertIn(root, doc, root)

    def test_the_patch_age_is_stated_as_a_number_not_a_vague_word(self):
        text = self.explain()
        self.assertIn("实测 322 天", text)
        self.assertNotIn("已相当陈旧", text)

    def test_the_no_spoofing_boundary_appears_in_explain_and_doc(self):
        for text, label in ((self.explain(), "explain"),
                            (self.DOC.read_text(encoding="utf-8"), "文档")):
            self.assertIn("不实现", text, label)

    def test_the_authoritative_acceptance_test_is_named_everywhere(self):
        sources = {"explain": self.explain(), "ticket": self.ticket(),
                   "ticket_en": self.ticket(english=True),
                   "doc": self.DOC.read_text(encoding="utf-8")}
        for label, text in sources.items():
            self.assertIn("AttestationRootHostTest", text, label)

    def test_the_english_ticket_stays_free_of_cjk(self):
        cjk = [c for c in self.ticket(english=True) if '\\u4e00' <= c <= '\\u9fff']
        self.assertEqual(cjk, [], f"英文工单含 CJK：{''.join(sorted(set(cjk)))}")

    def test_the_positive_control_gap_is_documented(self):
        doc = self.DOC.read_text(encoding="utf-8")
        self.assertIn("ASGXVB1806001948", doc)
        self.assertIn("never addressed", doc)
        self.assertIn("不主动探测第二台设备", doc)

    def test_the_firmware_conclusion_is_consistent(self):
        for text, label in ((self.explain(), "explain"),
                            (self.DOC.read_text(encoding="utf-8"), "文档")):
            self.assertIn("没有比设备当前版本更新的构建", text, label)


class ModelGeneralityTest(unittest.TestCase):
    """The positive control exposed two StepX-only assumptions.

    Running the model against a second phone (Honor ELZ-AN10) showed
    `system_boot` failing on a properly signed release build: the SDK check was
    hardcoded to 36 and the fingerprint check assumed product == device. Both
    are StepX-isms, not certification criteria.
    """

    def device(self, **overrides):
        props = {
            "ro.serialno": "TEST", "ro.build.tags": "release-keys",
            "ro.build.type": "user", "ro.boot.flash.locked": "1",
            "ro.boot.verifiedbootstate": "green",
            "ro.build.version.sdk": "34",
            "ro.build.version.security_patch": "2025-11-01",
            "ro.product.brand": "HONOR", "ro.product.manufacturer": "HONOR",
            "ro.product.model": "ELZ-AN10", "ro.product.device": "HNELZ",
            "ro.product.name": "ELZ-AN10",
            "ro.build.fingerprint": "HONOR/ELZ-AN10/HNELZ:14/HONORELZ-AN10/8.0.0.221CHNC00E211R4P7:user/release-keys",
        }
        props.update(overrides)
        return StubDevice(props=props, replies={("getenforce",): "Enforcing"})

    def test_a_release_build_passes_regardless_of_sdk_level(self):
        layer = model.probe_system_boot(self.device(), {})
        self.assertEqual(layer["state"], "pass")
        # SDK is evidence, not a criterion.
        self.assertEqual(layer["sdk"], "34")
        self.assertNotIn("SDK", [c["check"] for c in layer["checks"]])

    def test_a_fingerprint_with_product_differs_from_device_is_consistent(self):
        layer = model.probe_system_boot(self.device(), {})
        entry = next(c for c in layer["checks"] if c["check"] == "指纹与品牌/机型一致")
        self.assertIs(entry["ok"], True)

    def test_a_fingerprint_contradicting_its_own_brand_fails(self):
        layer = model.probe_system_boot(self.device(
            **{"ro.build.fingerprint": "OTHER/ELZ-AN10/HNELZ:14/x:user/release-keys"}), {})
        entry = next(c for c in layer["checks"] if c["check"] == "指纹与品牌/机型一致")
        self.assertIs(entry["ok"], False)
        self.assertEqual(layer["state"], "fail")

    def test_a_fingerprint_contradicting_its_own_device_fails(self):
        layer = model.probe_system_boot(self.device(
            **{"ro.build.fingerprint": "HONOR/ELZ-AN10/OTHER:14/x:user/release-keys"}), {})
        entry = next(c for c in layer["checks"] if c["check"] == "指纹与品牌/机型一致")
        self.assertIs(entry["ok"], False)

    def test_the_stepx_fingerprint_still_passes(self):
        layer = model.probe_system_boot(self.device(**{
            "ro.product.brand": "StepX", "ro.product.manufacturer": "StepX",
            "ro.product.model": "PZ261A", "ro.product.device": "pandora",
            "ro.product.name": "pandora",
            "ro.build.fingerprint": "StepX/pandora/pandora:16/BQ2A.260122.002-BP2A.250705.008/172:user/release-keys",
        }), {})
        self.assertEqual(layer["state"], "pass")

    def test_an_unlocked_bootloader_still_fails(self):
        layer = model.probe_system_boot(
            self.device(**{"ro.boot.flash.locked": "0"}), {})
        self.assertEqual(layer["state"], "fail")

    def test_the_security_patch_is_reported_as_evidence(self):
        layer = model.probe_system_boot(self.device(), {})
        self.assertEqual(layer["security_patch"], "2025-11-01")


