class VerdictTest(unittest.TestCase):
    def build(self, states=None, backend=200, listed=True, root_match=True):
        states = states or {}
        results = []
        for layer in model.LAYERS:
            result = {
                "layer": layer["id"], "title": layer["title"], "owner": layer["owner"],
                "state": states.get(layer["id"], "pass"), "checks": [], "note": "",
            }
            if layer["id"] == "rkp_and_catalog":
                result["checks"] = [
                    model.check("RKP signCertificates", backend, "200", backend == 200),
                    model.check("Google 认证设备目录收录", listed, True, listed is True),
                ]
            if layer["id"] == "key_attestation":
                result["verification"] = {"official_root_match": root_match}
            results.append(result)
        return results

    def test_every_layer_green_is_certified(self):
        self.assertTrue(model.certify(self.build()))

    def test_client_side_patch_alone_never_certifies(self):
        layers = self.build(backend=444, listed=False, root_match=False)
        self.assertEqual(layers[0]["state"], "pass")
        self.assertFalse(model.certify(layers))

    def test_each_layer_blocks_the_verdict(self):
        for layer_id in model.LAYER_IDS:
            with self.subTest(layer=layer_id):
                layers = self.build(states={layer_id: "fail"},
                                    backend=444 if layer_id == "rkp_and_catalog" else 200,
                                    listed=layer_id != "rkp_and_catalog",
                                    root_match=layer_id != "key_attestation")
                self.assertFalse(model.certify(layers), layer_id)

    def test_unprobed_layer_blocks_the_verdict(self):
        self.assertFalse(model.certify(self.build(states={"key_attestation": "unknown"})))

    def test_backend_444_blocks_the_verdict_even_when_every_layer_passes(self):
        self.assertFalse(model.certify(self.build(backend=444)))

    def test_blockers_name_the_owner_and_the_required_action(self):
        blockers = model.blockers_from(self.build(
            states={"key_attestation": "fail", "rkp_and_catalog": "fail"},
            backend=444, listed=False))
        self.assertEqual([blocker["layer"] for blocker in blockers],
                         ["key_attestation", "rkp_and_catalog"])
        self.assertEqual(blockers[0]["owner"], "oem")
        self.assertTrue(all(blocker["required_action"] for blocker in blockers))
        self.assertNotIn("client_admission", [blocker["layer"] for blocker in blockers])
        self.assertIn("444", blockers[1]["detail"])


class ReportTest(unittest.TestCase):
    def device(self):
        props = {
            "ro.product.brand": "StepX", "ro.product.manufacturer": "StepX",
            "ro.product.model": "PZ261A", "ro.product.device": "pandora",
            "ro.product.name": "pandora", "ro.build.tags": "release-keys",
            "ro.build.type": "user", "ro.boot.flash.locked": "1",
            "ro.boot.verifiedbootstate": "green", "ro.serialno": "TEST-SERIAL",
            "ro.build.version.sdk": "36", "remote_provisioning.hostname": "",
            "ro.build.fingerprint": "StepX/pandora/pandora:16/B/172:user/release-keys",
        }
        replies = {
            ("getprop", "ro.build.fingerprint"): props["ro.build.fingerprint"],
            ("dumpsys", "activity", "activities"): "mTopResumedActivity=U",
            ("pm", "list", "packages", "--user", "0"):
                "package:com.google.android.gsf\npackage:com.google.android.gms\npackage:com.android.vending",
            ("pm", "list", "packages", "-d", "--user", "0"): "",
            ("getenforce",): "Enforcing",
            ("cmd", "remote_provisioning", "dump"):
                "default:\n  hwVersion=3\n  rpcAuthorName=Qualcomm\n"
                "  uniqueId=fae4f65f6f801f67bbc9598ea5768b9d\n"
                "  supportedNumKeysInCsr=20\n",
            ("cmd", "remote_provisioning", "list"): "default\n",
        }
        return StubDevice(props, replies)

    def working_compat(self):
        """Stub the compatibility component; the real one needs a live device."""
        original = model.probe_compat_patch
        model.probe_compat_patch = lambda device, adb_path=None, script=None: {
            "available": True, "ok": True, "supported": True, "active": True,
            "can_rollback": True, "official_certification_changed": False,
            "scopes": {"gms": {"cache_active": True, "db_active": True}},
            "note": "stub",
        }
        return original

    def test_report_is_not_certified_and_separates_store_access(self):
        original = self.working_compat()
        try:
            result = model.report(self.device(), options(
                compat_active=True, firewall_allows=False, rkp_backend_status=444))
        finally:
            model.probe_compat_patch = original
        self.assertEqual(result["verdict"], "not_certified")
        self.assertFalse(result["certified"])
        self.assertTrue(result["store_access"]["usable"])
        admission = next(l for l in result["layers"] if l["layer"] == "client_admission")
        self.assertEqual(admission["state"], "pass")
        self.assertIn(result["verdict"], ("certified", "not_certified"))
        self.assertEqual([blocker["layer"] for blocker in result["blockers"]],
                         ["key_attestation", "rkp_and_catalog"])
        self.assertEqual({entry["check"] for entry in
                          next(l for l in result["layers"]
                               if l["layer"] == "rkp_and_catalog")["checks"]},
                         {"com.android.rkpdapp 已安装", "com.android.rkpdapp 正在运行",
                          "RKP HAL hwVersion", "RKP HAL rpcAuthorName", "RKP HAL uniqueId",
                          "remote_provisioning.hostname", "防火墙放行 IRemoteProvisioning",
                          "RKP signCertificates", "Google 认证设备目录收录"})

    def test_offline_report_marks_missing_evidence_as_unknown(self):
        result = model.report(self.device(), options())
        attestation = next(l for l in result["layers"] if l["layer"] == "key_attestation")
        self.assertEqual(attestation["state"], "unknown")
        self.assertFalse(result["certified"])

    def test_store_usability_is_not_claimed_without_the_component(self):
        # The compat component cannot answer on a stub device, so layer 1 must
        # stay `unknown` rather than asserting the store opens.
        result = model.report(self.device(), options())
        admission = next(l for l in result["layers"] if l["layer"] == "client_admission")
        self.assertEqual(admission["state"], "unknown")
        self.assertFalse(result["store_access"]["usable"])
        self.assertIsNone(admission["checks"][3]["ok"])

    def test_unavailable_device_degrades_instead_of_crashing(self):
        class Dead(StubDevice):
            def connected(self):
                return False

            def verify_identity(self):
                raise model.ProbeError("手机连接未授权或已离线，请重新连接")

            def shell(self, *args, timeout=40):
                raise model.ProbeError("手机连接未授权或已离线，请重新连接")

        result = model.report(Dead(), options())
        self.assertEqual(result["verdict"], "not_certified")
        self.assertTrue(all(layer["state"] == "unknown" for layer in result["layers"]))


class CatalogCacheTest(unittest.TestCase):
    def test_offline_never_claims_a_listing(self):
        result = model.fetch_catalog({"brand": "StepX", "model": "PZ261A"},
                                     "/nonexistent/catalog.json", offline=True)
        self.assertIsNone(result["listed"])
        self.assertFalse(result["from_cache"])

    def test_incomplete_identity_is_not_compared(self):
        result = model.fetch_catalog({"brand": "", "model": ""},
                                     "/nonexistent/catalog.json", offline=False)
        self.assertIsNone(result["listed"])

    def test_valid_cache_is_reused_without_network(self):
        import tempfile
        import time
        with tempfile.TemporaryDirectory() as scratch:
            path = Path(scratch) / "catalog.json"
            path.write_text(json.dumps({
                "identity": {"brand": "StepX", "model": "PZ261A"},
                "listed": False,
                "checked_at_epoch": time.time(),
                "note": "cached",
            }))
            result = model.fetch_catalog({"brand": "StepX", "model": "PZ261A"}, path, offline=False)
            self.assertTrue(result["from_cache"])
            self.assertIs(result["listed"], False)

    def test_stale_cache_is_not_reused(self):
        import tempfile
        import time
        with tempfile.TemporaryDirectory() as scratch:
            path = Path(scratch) / "catalog.json"
            path.write_text(json.dumps({
                "identity": {"brand": "StepX", "model": "PZ261A"},
                "listed": True,
                "checked_at_epoch": time.time() - 3 * 86400,
                "note": "cached",
            }))
            result = model.fetch_catalog({"brand": "StepX", "model": "PZ261A"}, path, offline=True)
            self.assertFalse(result["from_cache"])
            self.assertIsNone(result["listed"])


